use std::collections::BTreeMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Sample {
    pub position: i64,
    pub value: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Segment {
    pub start: i64,
    pub end: i64,
    pub samples: Vec<Sample>,
}

impl Segment {
    pub fn new(start: i64, end: i64, mut samples: Vec<Sample>) -> Option<Self> {
        if start > end || samples.iter().any(|s| s.position < start || s.position > end) {
            return None;
        }
        samples.sort_by_key(|s| s.position);
        if samples.windows(2).any(|w| w[0].position == w[1].position) {
            return None;
        }
        Some(Self { start, end, samples })
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct SegmentSet {
    segments: Vec<Segment>,
}

impl SegmentSet {
    pub fn new() -> Self { Self::default() }

    pub fn add(&mut self, segment: Segment) {
        self.segments.push(segment);
        self.normalize();
    }

    pub fn normalize(&mut self) {
        self.segments.sort_by_key(|s| (s.start, s.end));
        let mut output: Vec<Segment> = Vec::new();
        for segment in self.segments.drain(..) {
            if let Some(last) = output.last_mut() {
                if segment.start <= last.end {
                    last.end = last.end.max(segment.end);
                    let mut values: BTreeMap<i64, i64> = last.samples.iter().map(|s| (s.position, s.value)).collect();
                    for sample in segment.samples { values.insert(sample.position, sample.value); }
                    last.samples = values.into_iter().map(|(position, value)| Sample { position, value }).collect();
                    continue;
                }
            }
            output.push(segment);
        }
        self.segments = output;
    }

    pub fn subset(&self, start: i64, end: i64) -> Self {
        if start > end { return Self::new(); }
        let segments = self.segments.iter().filter_map(|segment| {
            let lo = segment.start.max(start);
            let hi = segment.end.min(end);
            if lo > hi { return None; }
            let samples = segment.samples.iter().copied().filter(|s| s.position >= lo && s.position <= hi).collect();
            Some(Segment { start: lo, end: hi, samples })
        }).collect();
        Self { segments }
    }

    pub fn is_empty(&self) -> bool { self.segments.is_empty() }
    pub fn segments(&self) -> &[Segment] { &self.segments }
}

