#[path = "solution.rs"]
mod solution;

use solution::{Segment, SegmentSet};

#[test]
fn segment_constructor_validates_boundaries() {
    assert!(Segment::new(5, 4, vec![]).is_none());
    assert!(Segment::new(5, 5, vec![]).is_some());
    assert!(Segment::new(i64::MIN, i64::MAX, vec![]).is_some());
}

#[test]
fn empty_sets_and_reversed_subsets_are_empty() {
    let set = SegmentSet::new();
    assert!(set.is_empty());
    assert!(set.subset(0, 10).is_empty());
    assert!(set.subset(10, 0).is_empty());
    assert_eq!(set.segments().len(), 0);
}

#[test]
fn add_transitively_merges_overlapping_and_touching_segments() {
    let mut set = SegmentSet::new();
    set.add(Segment::new(10, 12, vec![]).unwrap());
    set.add(Segment::new(1, 3, vec![]).unwrap());
    set.add(Segment::new(4, 9, vec![]).unwrap());

    assert_eq!(set.segments().len(), 1);
    assert_eq!(set.subset(1, 12).segments().len(), 1);
    assert!(set.subset(13, 20).is_empty());
}

#[test]
fn separated_segments_remain_separate_and_normalization_is_stable() {
    let mut set = SegmentSet::new();
    set.add(Segment::new(20, 25, vec![]).unwrap());
    set.add(Segment::new(1, 2, vec![]).unwrap());
    set.add(Segment::new(8, 10, vec![]).unwrap());
    assert_eq!(set.segments().len(), 3);

    set.normalize();
    assert_eq!(set.segments().len(), 3);
    set.normalize();
    assert_eq!(set.segments().len(), 3);
}

#[test]
fn subset_intersects_boundaries_without_mutating_source() {
    let mut set = SegmentSet::new();
    set.add(Segment::new(0, 10, vec![]).unwrap());
    set.add(Segment::new(20, 30, vec![]).unwrap());

    let subset = set.subset(5, 25);
    assert_eq!(subset.segments().len(), 2);
    assert_eq!(set.segments().len(), 2);
    assert!(set.subset(11, 19).is_empty());
}

#[test]
fn touching_check_does_not_overflow_at_integer_maximum() {
    let mut set = SegmentSet::new();
    set.add(Segment::new(i64::MAX, i64::MAX, vec![]).unwrap());
    set.add(Segment::new(i64::MAX - 1, i64::MAX - 1, vec![]).unwrap());
    assert_eq!(set.segments().len(), 1);
}

